type ebpfPolicy struct {
	name    string
	program *ebpf.Program
	close   func() error
}

const defaultPinBase = "/sys/fs/bpf"

func pinDirectory() string {
	if path := os.Getenv("BPF_PIN_PATH"); path != "" {
		return path
	}
	if base := os.Getenv("BPF_PIN_BASE"); base != "" {
		return base
	}
	return defaultPinBase
}

func targetMapPath() string {
	return filepath.Join(pinDirectory(), "pebble_udp_targets")
}

func loadEBPF(policy string, workers int) (*ebpfPolicy, error) {
	switch policy {
	case "default", "":
		return &ebpfPolicy{name: "default"}, nil
	case "round_robin":
		return loadRoundRobin(workers)
	case "agent":
		return loadAgent(workers)
	case "scan_split":
		return loadScanSplit(workers)
	case "hash":
		return loadHash(workers)
	default:
		return nil, ErrInvalidConfig(fmt.Sprintf("unknown policy %q", policy))
	}
}

