type ebpfPolicy struct {
	name    string
	program *ebpf.Program
	close   func() error
}

const defaultPinBase = "/sys/fs/bpf"

func pinDirectory() string {
	if path := os.Getenv("BPF_PIN_PATH"); path != "" {
		return path
	}
	if base := os.Getenv("BPF_PIN_BASE"); base != "" {
		return base
	}
	return defaultPinBase
}

func targetMapPath() string {
	return filepath.Join(pinDirectory(), "pebble_udp_targets")
}

func loadEBPF(policy string, workers int) (*ebpfPolicy, error) {
	switch policy {
	case "default", "":
		return &ebpfPolicy{name: "default"}, nil
	case "round_robin":
		return loadRoundRobin(workers)
	case "agent":
		return loadAgent(workers)
	case "scan_split":
		return loadScanSplit(workers)
	case "hash":
		return loadHash(workers)
	default:
		return nil, ErrInvalidConfig(fmt.Sprintf("unknown policy %q", policy))
	}
}

func updateTargetsMap(slot uint32, fd int) error {
	m, err := ebpf.LoadPinnedMap(targetMapPath(), nil)
	if err != nil {
		return fmt.Errorf("load target map: %w", err)
	}
	defer m.Close()

	value := uint32(fd)
	if err := m.Update(&slot, &value, ebpf.UpdateAny); err != nil {
		return fmt.Errorf("update target map: %w", err)
	}
	return nil
}

func clearTargets(numSlots int) error {
	m, err := ebpf.LoadPinnedMap(targetMapPath(), nil)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		return err
	}
	defer m.Close()

	for i := 0; i < numSlots; i++ {
		key := uint32(i)
		if err := m.Delete(&key); err != nil && !errors.Is(err, ebpf.ErrKeyNotExist) {
			return fmt.Errorf("clear slot %d: %w", i, err)
		}
	}
	return nil
}

